struct sk_buff *reassemble_ipv6_fragments(struct nf_ct_frag6_queue *fq, struct net_device *dev)
{
    struct sk_buff *skb = NULL;
    size_t payload_len = 0;
    int i;

    if (!fq || !dev) {
        return NULL;
    }

    for (i = 0; i < fq->q.pf; ++i) {
        struct sk_buff *frag = fq->q.fragments[i];
        if (!frag) {
            continue;
        }

        payload_len += frag->len;
        if (payload_len > IP6_MAX_MTU) {
            pr_debug("IPv6 reassembly: payload exceeds maximum MTU\n");
            goto error;
        }
    }

    skb = alloc_skb(payload_len, GFP_ATOMIC);
    if (!skb) {
        pr_debug("IPv6 reassembly: failed to allocate memory for reassembled packet\n");
        goto error;
    }

    for (i = 0; i < fq->q.pf; ++i) {
        struct sk_buff *frag = fq->q.fragments[i];
        if (!frag) {
            continue;
        }

        if (skb_tailroom(skb) < frag->len) {
            pr_debug("IPv6 reassembly: insufficient tailroom in reassembled packet\n");
            goto error;
        }

        skb_put_data(skb, frag->data, frag->len);
    }

    skb->dev = dev;
    skb->protocol = htons(ETH_P_IPV6);
    skb->ip_summed = CHECKSUM_NONE;

    return skb;

error:
    if (skb) {
        kfree_skb(skb);
    }
    return NULL;
}
